import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, uv, mul, float } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, PointLight } = ctx.THREE;

  // Root object
  const root = new Group();

  // Geometry (ratio from source rect 512x320 ≈ 1.6)
  const geometry = new PlaneGeometry(1.6, 1, 64, 64);

  // Node material
  const material = new MeshStandardNodeMaterial();
  material.roughness = 0.6;
  material.metalness = 0.3;
  material.clearcoat = 0.2;
  material.color = 0xffffff; // base white, texture will dominate

  // Mesh
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Accent rim light (optional, subtle)
  const rimLight = new PointLight('#ff2a38', 0.5);
  rimLight.position.set(0, 0, 1);
  root.add(rimLight);

  // Load textures asynchronously
  let colorTex = null;
  let depthTex = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      colorTex = tex;
      material.map = tex;
      material.mapNode = texture(tex, uv());
      material.needsUpdate = true;
    });
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthTex = tex;
      // Displacement intensity subtle
      material.displacementNode = mul(texture(tex, uv()), float(0.05));
      material.needsUpdate = true;
    });
  }

  // Interaction: hover rise‑in
  const riseTimeline = gsap.timeline({ paused: true, defaults: { ease: 'power3.out' } });
  riseTimeline.to(mesh.position, { y: '+=0.15', duration: 0.15 });

  // Interaction handlers stored in userData
  root.userData.handlers = {
    hoverEnter: () => riseTimeline.play(),
    hoverLeave: () => riseTimeline.reverse(),
    click: () => ctx.emit('hub-home.select')
  };

  // Apply cinematic primitives
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const handle = ctx.primitives[prim.name](root, prim.params);
      primitiveHandles.push(handle);
    }
  }

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose textures if they were loaded
    if (colorTex && colorTex.dispose) colorTex.dispose();
    if (depthTex && depthTex.dispose) depthTex.dispose();

    // Kill GSAP timelines
    riseTimeline.kill();

    // Cleanup primitives
    for (const h of primitiveHandles) {
      if (h.timeline && h.timeline.kill) h.timeline.kill();
      if (h.cleanup) h.cleanup();
    }
  };

  return root;
}
